/**
 * config.js — binary task
 * Sequences loaded from task/sequences/binary_sequences.json
 * (single master copy — generated by task/generate_sequences.py)
 * p_range=0.2..0.8, values {-1,+1}
 */
import sequencesData from '../../sequences/binary_sequences.json';

// ── Parameters ────────────────────────────────────────────────────────────
// Set TEST_MODE=true for quick dev runs: skip/take tutorial, 20 trials, 500ms BTI
const TEST_MODE              = false;

const N_TRIALS_TO_RUN        = TEST_MODE ? 20  : 24;  // 6 seqs × 4 reps
const N_OBS_TO_RUN           = 15;
const SHOW_SLIDER_VALUE      = true;    // float label above thumb
const SLIDER_DEFAULT         = 'none';  // 'none' | 'last'
const DEFAULT_VALUE          = 50;      // midpoint of [0,100] slider
const DEBUG_FAST = false;   // set true for fast automated testing only
const BTI_MS             = TEST_MODE ? 500  : 3000;
const ITI_SHORT_MS       = 1000;
const T_OBS_MS           = 7000;
const SHOW_TRIAL_PERFORMANCE = true;
const DISTRACTOR_TYPE        = 'none';  // 'none' | 'iti_length' | 'popup'

// Practice (tutorial) — fixed sequence: B B R B R (+1=blue, -1=red)
const practiceValues = [1, 1, -1, 1, -1];  // true_p ≈ 0.6
const PRACTICE_P     = 0.6;

export const config = {
  taskType:             'binary',
  sequences:            sequencesData.map(
                          s => ({ ...s, values: s.values.slice(0, N_OBS_TO_RUN) })
                        ),
  nTrialsDefault:       N_TRIALS_TO_RUN,  // used by buildAndRun when no override
  practiceValues,
  practiceMean:         PRACTICE_P,
  practiceStd:          0,
  showSliderValue:      SHOW_SLIDER_VALUE,
  sliderDefault:        SLIDER_DEFAULT,
  defaultValue:         DEFAULT_VALUE,
  btiMs:               BTI_MS,
  itiShortMs:         ITI_SHORT_MS,
  tObsMs:               T_OBS_MS,
  showTrialPerformance: SHOW_TRIAL_PERFORMANCE,
  distractorType:       DISTRACTOR_TYPE,
  testMode:             TEST_MODE,
};
